def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    index = {ch: i for i, ch in enumerate(alphabet)}

    children = [[-1] * size]
    fail = [0]
    terminal = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = index[ch]
            if children[state][c] == -1:
                children[state][c] = len(children)
                children.append([-1] * size)
                fail.append(0)
                terminal.append(False)
            state = children[state][c]
        terminal[state] = True

    queue = deque()
    for c in range(size):
        state = children[0][c]
        if state == -1:
            children[0][c] = 0
        else:
            queue.append(state)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[fail[state]]
        for c in range(size):
            nxt = children[state][c]
            if nxt == -1:
                children[state][c] = children[fail[state]][c]
            else:
                fail[nxt] = children[fail[state]][c]
                queue.append(nxt)

    safe = [state for state in range(len(children)) if not terminal[state]]
    ids = {state: i for i, state in enumerate(safe)}
    count = len(safe)

    matrix = [[0] * count for _ in range(count)]
    for state in safe:
        row = matrix[ids[state]]
        for nxt in children[state]:
            if not terminal[nxt]:
                row[ids[nxt]] += 1

    vector = [0] * count
    vector[ids[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    row = matrix[i]
                    for j in range(count):
                        result[j] += value * row[j]
            vector = [value % mod for value in result]

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                result = squared[i]
                for k, value in enumerate(matrix[i]):
                    if value:
                        row = matrix[k]
                        for j in range(count):
                            result[j] += value * row[j]
                squared[i] = [value % mod for value in result]
            matrix = squared

    return sum(vector) % mod
